-- PROPOSAL ONLY: not applied to the running app or the transitional PostgreSQL schema.
-- Later row-owned design for a Flask API using OIDC and one paper account per user.
-- UUIDs are generated by the API. All monetary values are integer INR paise.

BEGIN;
CREATE SCHEMA paperlane_app;

-- The identity provider owns credentials. Retain only a validated OIDC identity mapping.
CREATE TABLE paperlane_app.app_users (
    id UUID PRIMARY KEY,
    oidc_issuer TEXT NOT NULL,
    oidc_subject TEXT NOT NULL,
    email_for_display TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (oidc_issuer, oidc_subject)
);

CREATE TABLE paperlane_app.paper_accounts (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL UNIQUE REFERENCES paperlane_app.app_users(id),
    initial_cash_paise BIGINT NOT NULL DEFAULT 100000000,
    cash_paise BIGINT NOT NULL DEFAULT 100000000,
    realized_pnl_paise BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (initial_cash_paise > 0)
);

-- Shared catalogue. A demo index can be viewed but cannot be ordered.
CREATE TABLE paperlane_app.instruments (
    id TEXT PRIMARY KEY,
    exchange TEXT NOT NULL CHECK (exchange IN ('NSE', 'BSE', 'DEMO')),
    symbol TEXT NOT NULL,
    name TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('INDEX', 'EQUITY', 'OPTION')),
    underlying_id TEXT REFERENCES paperlane_app.instruments(id),
    option_type TEXT CHECK (option_type IN ('CE', 'PE')),
    strike_paise BIGINT,
    expiry_date DATE,
    lot_size INTEGER NOT NULL DEFAULT 1 CHECK (lot_size > 0),
    tick_paise INTEGER NOT NULL DEFAULT 1 CHECK (tick_paise > 0),
    source_catalogue_id TEXT,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK (
        kind <> 'OPTION' OR
        (underlying_id IS NOT NULL AND option_type IS NOT NULL
         AND strike_paise > 0 AND expiry_date IS NOT NULL)
    )
);

-- One shared quote and optional observed bars per instrument, with source labels.
CREATE TABLE paperlane_app.quotes (
    instrument_id TEXT PRIMARY KEY REFERENCES paperlane_app.instruments(id),
    bid_paise BIGINT NOT NULL CHECK (bid_paise > 0),
    ask_paise BIGINT NOT NULL CHECK (ask_paise > 0),
    last_paise BIGINT NOT NULL CHECK (last_paise > 0),
    source TEXT NOT NULL CHECK (source IN ('SYNTHETIC', 'DELAYED', 'LICENSED_LIVE')),
    observed_at TIMESTAMPTZ NOT NULL,
    CHECK (bid_paise <= ask_paise)
);

CREATE TABLE paperlane_app.price_bars (
    instrument_id TEXT NOT NULL REFERENCES paperlane_app.instruments(id),
    interval_seconds INTEGER NOT NULL CHECK (interval_seconds > 0),
    started_at TIMESTAMPTZ NOT NULL,
    source TEXT NOT NULL,
    open_paise BIGINT NOT NULL CHECK (open_paise > 0),
    high_paise BIGINT NOT NULL CHECK (high_paise > 0),
    low_paise BIGINT NOT NULL CHECK (low_paise > 0),
    close_paise BIGINT NOT NULL CHECK (close_paise > 0),
    volume BIGINT CHECK (volume >= 0),
    PRIMARY KEY (instrument_id, interval_seconds, started_at, source),
    CHECK (high_paise >= GREATEST(open_paise, close_paise, low_paise)),
    CHECK (low_paise <= LEAST(open_paise, close_paise, high_paise))
);

CREATE TABLE paperlane_app.positions (
    account_id UUID NOT NULL REFERENCES paperlane_app.paper_accounts(id),
    instrument_id TEXT NOT NULL REFERENCES paperlane_app.instruments(id),
    quantity BIGINT NOT NULL CHECK (quantity <> 0),
    average_entry_paise BIGINT NOT NULL CHECK (average_entry_paise > 0),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (account_id, instrument_id)
);

CREATE TABLE paperlane_app.trade_plans (
    id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES paperlane_app.paper_accounts(id),
    instrument_id TEXT NOT NULL REFERENCES paperlane_app.instruments(id),
    reason TEXT NOT NULL CHECK (length(trim(reason)) BETWEEN 1 AND 2000),
    exit_rule TEXT NOT NULL CHECK (length(trim(exit_rule)) BETWEEN 1 AND 2000),
    max_loss_paise BIGINT NOT NULL CHECK (max_loss_paise > 0),
    confidence SMALLINT CHECK (confidence BETWEEN 1 AND 5),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, account_id)
);

CREATE TABLE paperlane_app.orders (
    id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES paperlane_app.paper_accounts(id),
    instrument_id TEXT NOT NULL REFERENCES paperlane_app.instruments(id),
    side TEXT NOT NULL CHECK (side IN ('BUY', 'SELL')),
    order_type TEXT NOT NULL CHECK (order_type IN ('MARKET', 'LIMIT', 'STOP_LIMIT')),
    quantity BIGINT NOT NULL CHECK (quantity > 0),
    filled_quantity BIGINT NOT NULL DEFAULT 0 CHECK (filled_quantity >= 0),
    limit_price_paise BIGINT CHECK (limit_price_paise > 0),
    trigger_price_paise BIGINT CHECK (trigger_price_paise > 0),
    status TEXT NOT NULL CHECK (status IN ('PENDING', 'PARTIAL', 'FILLED', 'CANCELLED', 'REJECTED')),
    reserved_paise BIGINT NOT NULL DEFAULT 0 CHECK (reserved_paise >= 0),
    plan_id UUID,
    client_request_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, account_id),
    UNIQUE (account_id, client_request_id),
    FOREIGN KEY (plan_id, account_id) REFERENCES paperlane_app.trade_plans(id, account_id),
    CHECK (filled_quantity <= quantity),
    CHECK (
        (order_type = 'MARKET' AND limit_price_paise IS NULL AND trigger_price_paise IS NULL) OR
        (order_type = 'LIMIT' AND limit_price_paise IS NOT NULL AND trigger_price_paise IS NULL) OR
        (order_type = 'STOP_LIMIT' AND limit_price_paise IS NOT NULL AND trigger_price_paise IS NOT NULL)
    )
);

-- A trade report is reconstructed from fills; do not store a second mutable P&L truth.
CREATE TABLE paperlane_app.fills (
    id UUID PRIMARY KEY,
    order_id UUID NOT NULL,
    account_id UUID NOT NULL,
    quantity BIGINT NOT NULL CHECK (quantity > 0),
    price_paise BIGINT NOT NULL CHECK (price_paise > 0),
    fee_paise BIGINT NOT NULL CHECK (fee_paise >= 0),
    filled_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    indicator_snapshot JSONB,
    UNIQUE (id, account_id),
    FOREIGN KEY (order_id, account_id) REFERENCES paperlane_app.orders(id, account_id)
);

-- Append-only entries explain cash changes. The account row is a cached balance.
CREATE TABLE paperlane_app.account_ledger (
    id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES paperlane_app.paper_accounts(id),
    fill_id UUID,
    entry_type TEXT NOT NULL CHECK (entry_type IN ('INITIAL_CREDIT', 'TRADE_CASH', 'FEE', 'RESET_ADJUSTMENT')),
    amount_paise BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (fill_id, account_id) REFERENCES paperlane_app.fills(id, account_id)
);

CREATE TABLE paperlane_app.learning_progress (
    user_id UUID NOT NULL REFERENCES paperlane_app.app_users(id),
    content_kind TEXT NOT NULL CHECK (content_kind IN ('LESSON', 'EXERCISE')),
    content_id TEXT NOT NULL,
    completed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, content_kind, content_id)
);

CREATE TABLE paperlane_app.journal_notes (
    id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES paperlane_app.paper_accounts(id),
    note TEXT NOT NULL CHECK (length(trim(note)) BETWEEN 1 AND 5000),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX orders_account_time_idx ON paperlane_app.orders (account_id, created_at DESC);
CREATE INDEX orders_pending_idx ON paperlane_app.orders (created_at) WHERE status IN ('PENDING', 'PARTIAL');
CREATE INDEX fills_account_time_idx ON paperlane_app.fills (account_id, filled_at DESC);
CREATE INDEX plans_account_time_idx ON paperlane_app.trade_plans (account_id, created_at DESC);
CREATE INDEX journal_account_time_idx ON paperlane_app.journal_notes (account_id, created_at DESC);
CREATE INDEX bars_instrument_time_idx ON paperlane_app.price_bars (instrument_id, interval_seconds, started_at DESC);

-- Keep application tables out of public API schemas; the Flask backend is the data boundary.
REVOKE ALL ON SCHEMA paperlane_app FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA paperlane_app FROM PUBLIC;
COMMIT;
